export interface ConnectorConfig {
  /** Zendesk subdomain (e.g., 'mycompany' for mycompany.zendesk.com) */
  zendeskSubdomain: string
  /** Zendesk API token (format: email/token:api_token) */
  zendeskApiToken: string
  /** Optional injected fetch for testing */
  fetch?: typeof fetch
}

export interface IntercomWebhookPayload {
  topic: string
  data: {
    item: {
      id: string
      url: string
      tags: {
        tags: Array<{ name: string; id: string }>
        type: string
      }
    }
  }
}

export interface ZendeskTicketResponse {
  ticket: {
    id: number
    subject: string
    description: string
    url: string
  }
}

export interface HandleResult {
  ticketId: number
  ticketUrl: string
}

function getFetch(config: ConnectorConfig): typeof fetch {
  return config.fetch ?? fetch
}

function validatePayload(payload: unknown): asserts payload is IntercomWebhookPayload {
  if (!payload || typeof payload !== 'object') {
    throw new Error('Payload must be an object')
  }
  const p = payload as Record<string, unknown>
  if (p.topic !== 'conversation.tag') {
    throw new Error(`Expected topic "conversation.tag", got "${p.topic}"`)
  }
  if (!p.data || typeof p.data !== 'object') {
    throw new Error('Missing data object')
  }
  const data = p.data as Record<string, unknown>
  if (!data.item || typeof data.item !== 'object') {
    throw new Error('Missing data.item object')
  }
  const item = data.item as Record<string, unknown>
  if (typeof item.id !== 'string' || !item.id) {
    throw new Error('Missing or empty conversation id')
  }
  if (typeof item.url !== 'string' || !item.url) {
    throw new Error('Missing or empty conversation url')
  }
  if (!item.tags || typeof item.tags !== 'object') {
    throw new Error('Missing tags object')
  }
  const tags = item.tags as Record<string, unknown>
  if (!Array.isArray(tags.tags)) {
    throw new Error('Missing tags.tags array')
  }
}

function hasRefundTag(payload: IntercomWebhookPayload): boolean {
  return payload.data.item.tags.tags.some(tag => tag.name === 'refund')
}

export async function handle(
  payload: unknown,
  config: ConnectorConfig
): Promise<HandleResult> {
  validatePayload(payload)
  const typedPayload = payload as IntercomWebhookPayload

  if (!hasRefundTag(typedPayload)) {
    throw new Error('Conversation does not have the "refund" tag')
  }

  const { id, url } = typedPayload.data.item
  const subject = url
  const description = `Intercom conversation ID: ${id}\nURL: ${url}`

  const zendeskUrl = `https://${config.zendeskSubdomain}.zendesk.com/api/v2/tickets.json`
  const authHeader = `Bearer ${config.zendeskApiToken}`

  const requestBody = {
    ticket: {
      subject,
      comment: {
        body: description
      }
    }
  }

  const fetchFn = getFetch(config)
  const response = await fetchFn(zendeskUrl, {
    method: 'POST',
    headers: {
      'Authorization': authHeader,
      'Content-Type': 'application/json'
    },
    body: JSON.stringify(requestBody)
  })

  if (!response.ok) {
    throw new Error(`Zendesk API error: ${response.status} ${response.statusText} for POST ${zendeskUrl}`)
  }

  const result = await response.json() as ZendeskTicketResponse
  return {
    ticketId: result.ticket.id,
    ticketUrl: result.ticket.url
  }
}

